	let url = `https://api5-normal-sinfonlineb.fqnovel.com/reading/bookapi/multi-detail/v/?aid=1967&iid=1&version_code=999&book_id=${bookid}`;
        let last =JSON.parse(java.ajax(url)).data[0]; 
